from svg import box, t, arrow, line, svg

COLS = [(20, 's-card', 'THE ROBOT MYTH', 'an irresistible technique', 'members have no will left', 'courts and the APA: not shown'),
        (410, 's-box-a', 'BOUNDED CHOICE', 'real choices, rigged prices', 'pressure, deception, exit costs', 'where most scholars land'),
        (800, 's-card', 'THE FREE-MARKET MYTH', 'members are free shoppers', 'nothing was done to anyone', 'ignores documented control')]
FIG = svg(1180, 300, 'Two myths about cult influence and the middle ground',
          ''.join(box(x, 30, 360, 200, c) + t(x + 180, 72, h, 's-t') + t(x + 180, 118, a, 's-t-b') + t(x + 180, 152, b, 's-t-sm') +
                  t(x + 180, 200, v, 's-t-sm') for x, c, h, a, b, v in COLS) +
          arrow(395, 130, 405, 130) + arrow(785, 130, 775, 130) +
          t(590, 280, 'The useful questions sit in the middle: what was hidden, what did leaving cost, who set the prices?', 's-t-sm'))

